<?php
require_once __DIR__ . '/config_medical.php';medical_require_permission('view');if($_SERVER['REQUEST_METHOD']!=='POST'||!medical_verify_csrf(isset($_POST['csrf_token'])?$_POST['csrf_token']:'')){http_response_code(400);die('Bad Request');}
$id=(int)$_POST['id'];$row=medical_get_request($id);$u=medical_current_user();if(!$row||(!medical_is_admin()&&(int)$row['user_id']!==(int)$u['id'])||in_array($row['status'],array('completed','cancelled'),true)){http_response_code(403);die('Forbidden');}
$requester=trim($_POST['requester_name']);$dept=trim($_POST['department']);$phone=trim($_POST['contact_phone']);$location=trim($_POST['location']);$asset=trim($_POST['asset_code']);$name=trim($_POST['equipment_name']);$category=trim($_POST['category']);$serial=trim($_POST['serial_no']);$problem=trim($_POST['problem_type']);$priority=trim($_POST['priority']);$detail=trim($_POST['problem_detail']);if($requester===''||$dept===''||$location===''||$name===''||$detail===''){medical_flash('error','กรุณากรอกข้อมูลให้ครบ');header('Location:edit.php?id='.$id);exit;}
$stmt=$conn->prepare("UPDATE medical_repair_requests SET requester_name=?,department=?,contact_phone=?,location=?,asset_code=?,equipment_name=?,category=?,serial_no=?,problem_type=?,priority=?,problem_detail=? WHERE id=?");$stmt->bind_param('sssssssssssi',$requester,$dept,$phone,$location,$asset,$name,$category,$serial,$problem,$priority,$detail,$id);$ok=$stmt->execute();$err=$stmt->error;$stmt->close();if($ok){medical_log($id,'edit',$row['status'],$row['status'],'แก้ไขข้อมูลแจ้งซ่อม');medical_flash('success','แก้ไขข้อมูลเรียบร้อยแล้ว');}else medical_flash('error','แก้ไขไม่สำเร็จ: '.$err);header('Location:detail.php?id='.$id);exit;
